    ["Срочных замечаний нет."] = {"Nothing needs your attention right now.","Im Moment gibt es nichts zu tun.","Rien d’urgent pour l’instant.","No hay nada urgente ahora.","Nada urgente no momento.","지금 급히 살펴볼 것은 없습니다.","目前没有需要处理的事项。","目前沒有需要處理的事項。"},
    ["Появились новые возможности"] = {"New options are available","Neue Möglichkeiten sind verfügbar","De nouvelles options sont disponibles","Hay nuevas opciones disponibles","Há novas opções disponíveis","새로 할 수 있는 일이 생겼습니다","有新内容可学","有新內容可學"},
    ["Осмотри моего персонажа: что стоит исправить в первую очередь и почему?"] = {"Look over my character: what should I fix first, and why?","Sieh dir meinen Charakter an: Was sollte ich zuerst verbessern und warum?","Examine mon personnage : que dois-je corriger en premier, et pourquoi ?","Revisa mi personaje: ¿qué debería corregir primero y por qué?","Analise meu personagem: o que devo corrigir primeiro e por quê?","내 캐릭터를 살펴봐 줘. 무엇을 먼저 고쳐야 하고 이유는 뭐야?","检查一下我的角色：我应该先改进什么，为什么？","檢查一下我的角色：我應該先改進什麼，為什麼？"},
    ["Свободные очки талантов"] = {"Unspent talent points","Unverteilte Talentpunkte","Points de talent non dépensés","Puntos de talento sin gastar","Pontos de talento não gastos","쓰지 않은 특성 점수","未分配的天赋点","未分配的天賦點"},
    ["Открой окно талантов и вложи их. Советник подскажет выбор."] = {"Open the talent window and spend them. The advisor can suggest a choice.","Öffne das Talentfenster und verteile sie. Der Berater schlägt eine Wahl vor.","Ouvre la fenêtre des talents et dépense-les. Le conseiller peut suggérer un choix.","Abre la ventana de talentos y gástalos. El consejero puede sugerir una opción.","Abra a janela de talentos e gaste-os. O conselheiro pode sugerir uma escolha.","특성 창을 열어 투자하세요. 조언자가 선택을 제안해 줍니다.","打开天赋窗口分配它们。顾问可以给出建议。","開啟天賦視窗分配它們。顧問可以給出建議。"},
    ["Очки талантов вложены"] = {"Talent points are spent","Talentpunkte sind verteilt","Les points de talent sont dépensés","Los puntos de talento están gastados","Os pontos de talento estão gastos","특성 점수를 모두 사용함","天赋点已分配","天賦點已分配"},
    ["У тренера ждут новые заклинания"] = {"New spells are waiting at the trainer","Beim Lehrer warten neue Zauber","De nouveaux sorts t’attendent chez le maître","Hay hechizos nuevos esperando en el instructor","Há feitiços novos esperando no instrutor","상급자에게 새 주문이 기다리고 있습니다","训练师处有新法术可学","訓練師處有新法術可學"},
    ["Нет жезла"] = {"No wand","Kein Zauberstab","Pas de baguette","Sin varita","Sem varinha","마법봉 없음","没有魔杖","沒有魔杖"},
    ["Жезл добивает врагов без расхода маны. Его продают на аукционе и делают зачарователи."] = {"A wand finishes enemies without spending mana. Look on the auction house or ask an enchanter.","Ein Zauberstab erledigt Gegner ohne Manakosten. Schau im Auktionshaus nach oder frag einen Verzauberer.","Une baguette achève les ennemis sans dépenser de mana. Cherche à l’hôtel des ventes ou demande à un enchanteur.","Una varita remata enemigos sin gastar maná. Busca en la casa de subastas o pide una a un encantador.","Uma varinha finaliza inimigos sem gastar mana. Procure na casa de leilões ou peça a um encantador.","마법봉은 마나 없이 적을 마무리합니다. 경매장에서 찾거나 마법부여사에게 부탁하세요.","魔杖可以不耗法力地收尾敌人。可在拍卖行购买，或请附魔师制作。","魔杖可以不耗法力地收尾敵人。可在拍賣場購買，或請附魔師製作。"},
    ["Снаряжение почти сломано"] = {"Gear is nearly broken","Ausrüstung fast kaputt","Équipement presque cassé","Equipo casi roto","Equipamento quase quebrado","장비가 거의 파손됨","装备即将损坏","裝備即將損壞"},
    ["Зайди к торговцу с ремонтом."] = {"Visit a vendor who repairs.","Besuche einen Händler, der repariert.","Passe chez un marchand qui répare.","Visita a un vendedor que repare.","Visite um comerciante que faça reparos.","수리 상인을 찾아가세요.","去找可以修理的商人。","去找可以修理的商人。"},
    ["Нет бонуса от еды"] = {"No food bonus","Kein Nahrungsbonus","Pas de bonus de nourriture","Sin bonificación de comida","Sem bônus de comida","음식 효과 없음","没有食物增益","沒有食物增益"},
    ["В Forever сытость от приготовленной еды даёт +5% опыта за убийства. Эффект зависит от блюда."] = {"In Forever, being Well Fed from cooked food gives +5% experience from kills. The effect depends on the dish.","In Forever gibt „Satt“ durch gekochtes Essen +5 % Erfahrung für Kills. Der Effekt hängt vom Gericht ab.","Dans Forever, être Bien nourri grâce à un plat cuisiné donne +5 % d’expérience sur les monstres tués. L’effet dépend du plat.","En Forever, estar Bien alimentado con comida cocinada da +5 % de experiencia por muertes. El efecto depende del plato.","No Forever, estar Bem Alimentado com comida preparada dá +5% de experiência por abates. O efeito depende do prato.","Forever에서는 요리한 음식의 포만감이 처치 경험치를 5% 올려 줍니다. 효과는 음식마다 다릅니다.","在 Forever 中，食用烹饪食物获得的“进食充分”可使击杀经验 +5%。效果取决于具体食物。","在 Forever 中，食用烹飪食物獲得的「進食充分」可使擊殺經驗 +5%。效果取決於具體食物。"},
    ["Бонус от еды активен"] = {"Food bonus is active","Nahrungsbonus ist aktiv","Le bonus de nourriture est actif","La bonificación de comida está activa","O bônus de comida está ativo","음식 효과 적용 중","食物增益生效中","食物增益生效中"},
    ["Навык достиг предела. Следующий ранг открывает тренер профессии."] = {"The skill is at its cap. A profession trainer unlocks the next rank.","Die Fertigkeit ist am Limit. Ein Berufslehrer schaltet den nächsten Rang frei.","La compétence est au maximum. Un maître de métier débloque le rang suivant.","La habilidad está al máximo. Un instructor de profesión desbloquea el siguiente rango.","A perícia está no limite. Um instrutor de profissão libera o próximo grau.","기술이 한계에 도달했습니다. 전문기술 상급자가 다음 단계를 열어 줍니다.","技能已达上限。专业训练师可解锁下一级。","技能已達上限。專業訓練師可解鎖下一級。"},
    ["До следующего костра для лагеря: {1}"] = {"Until the next campfire for your camp: {1}","Bis zum nächsten Lagerfeuer für dein Lager: {1}","Avant le prochain feu de camp : {1}","Hasta la próxima hoguera para tu campamento: {1}","Até a próxima fogueira para o acampamento: {1}","다음 야영지 모닥불까지: {1}","距离下一种营地篝火：{1}","距離下一種營地篝火：{1}"},
    ["До следующего предмета лагеря: {1}"] = {"Until the next camp item: {1}","Bis zum nächsten Lagergegenstand: {1}","Avant le prochain objet de camp : {1}","Hasta el próximo objeto de campamento: {1}","Até o próximo item de acampamento: {1}","다음 야영지 물품까지: {1}","距离下一件营地物品：{1}","距離下一件營地物品：{1}"},
