    ["Известная ошибка"] = {"Known bug","Bekannter Fehler","Bug connu","Error conocido","Erro conhecido","알려진 버그","已知错误","已知錯誤"},
    ["Blizzard это исправила"] = {"Blizzard has fixed this","Blizzard hat das behoben","Blizzard a corrigé cela","Blizzard lo ha corregido","A Blizzard corrigiu isto","블리자드가 수정함","暴雪已修复","暴雪已修復"},
    ["Условия задания изменились"] = {"The quest’s requirements changed","Die Anforderungen der Quest wurden geändert","Les conditions de la quête ont changé","Los requisitos de la misión cambiaron","Os requisitos da missão mudaram","퀘스트 조건이 변경됨","任务条件已更改","任務條件已更改"},
    ["Задание работает как задумано"] = {"The quest works as intended","Die Quest funktioniert wie vorgesehen","La quête fonctionne comme prévu","La misión funciona como está previsto","A missão funciona como previsto","퀘스트는 정상 동작함","任务运作正常","任務運作正常"},
    ["Подтверждений ошибки не нашлось"] = {"No confirmation of a bug was found","Keine Bestätigung für einen Fehler gefunden","Aucune confirmation de bug trouvée","No se encontró confirmación de un error","Nenhuma confirmação de erro encontrada","버그로 확인된 사례 없음","未找到错误的佐证","未找到錯誤的佐證"},
