    ["Осталось сдать его."] = {"All that is left is to turn it in.","Du musst sie nur noch abgeben.","Il ne reste qu’à la rendre.","Solo queda entregarla.","Só falta entregá-la.","이제 보고만 하면 됩니다.","只需交付即可。","只需交付即可。"},
    ["Сумки полны"] = {"Bags are full","Taschen sind voll","Sacs pleins","Bolsas llenas","Bolsas cheias","가방이 가득 참","背包已满","背包已滿"},
    ["Предмет задания некуда положить. Освободи ячейку."] = {"A quest item has nowhere to go. Free a slot.","Ein Questgegenstand hat keinen Platz. Mach einen Platz frei.","Un objet de quête n’a nulle part où aller. Libère un emplacement.","Un objeto de misión no tiene sitio. Libera una casilla.","Um item de missão não tem onde ficar. Libere um espaço.","퀘스트 아이템을 넣을 곳이 없습니다. 칸을 비우세요.","任务物品无处可放。请腾出一个格子。","任務物品無處可放。請騰出一個格子。"},
    ["Задание выше твоего уровня"] = {"The quest is above your level","Die Quest liegt über deiner Stufe","La quête dépasse ton niveau","La misión supera tu nivel","A missão está acima do seu nível","퀘스트가 내 레벨보다 높음","任务等级高于你","任務等級高於你"},
    ["Уровень задания {1}, твой {2}."] = {"The quest is level {1}; you are level {2}.","Die Quest ist Stufe {1}, du bist Stufe {2}.","La quête est de niveau {1}, tu es niveau {2}.","La misión es de nivel {1}; tú eres nivel {2}.","A missão é de nível {1}; você é nível {2}.","퀘스트 레벨 {1}, 내 레벨 {2}.","任务等级 {1}，你的等级 {2}。","任務等級 {1}，你的等級 {2}。"},
    ["Задание для подземелья"] = {"Dungeon quest","Dungeonquest","Quête de donjon","Misión de mazmorra","Missão de masmorra","던전 퀘스트","地下城任务","地城任務"},
    ["Цель находится в подземелье и рассчитана на группу."] = {"The objective is inside a dungeon and meant for a group.","Das Ziel liegt in einem Dungeon und ist für eine Gruppe gedacht.","L’objectif se trouve dans un donjon et est prévu pour un groupe.","El objetivo está en una mazmorra y es para un grupo.","O objetivo fica em uma masmorra e é para um grupo.","목표는 던전 안에 있으며 파티용입니다.","目标位于地下城内，需要组队完成。","目標位於地城內，需要組隊完成。"},
    ["Ты в облике призрака"] = {"You are a ghost","Du bist ein Geist","Tu es un fantôme","Eres un fantasma","Você é um fantasma","유령 상태","你处于灵魂状态","你處於靈魂狀態"},
    ["Сначала вернись к телу."] = {"Return to your body first.","Kehre zuerst zu deinem Körper zurück.","Retourne d’abord à ton corps.","Vuelve primero a tu cuerpo.","Volte primeiro ao seu corpo.","먼저 시체로 돌아가세요.","请先回到尸体处。","請先回到屍體處。"},
    ["Blizzard упоминает это задание в исправлениях"] = {"Blizzard mentions this quest in the hotfixes","Blizzard erwähnt diese Quest in den Hotfixes","Blizzard mentionne cette quête dans les correctifs","Blizzard menciona esta misión en las correcciones","A Blizzard menciona esta missão nas correções","블리자드 핫픽스에 이 퀘스트가 언급됨","暴雪在热修中提到了此任务","暴雪在熱修中提到了此任務"},
    ["Ищу это задание в исправлениях и известных ошибках…"] = {"Looking for this quest in hotfixes and known issues…","Diese Quest wird in Hotfixes und bekannten Problemen gesucht…","Recherche de cette quête dans les correctifs et problèmes connus…","Buscando esta misión en correcciones y problemas conocidos…","Procurando esta missão nas correções e problemas conhecidos…","핫픽스와 알려진 문제에서 이 퀘스트를 찾는 중…","正在热修和已知问题中查找此任务…","正在熱修和已知問題中查找此任務…"},
    ["Не удалось проверить задание."] = {"Could not check the quest.","Die Quest konnte nicht geprüft werden.","Impossible de vérifier la quête.","No se pudo comprobar la misión.","Não foi possível verificar a missão.","퀘스트를 확인하지 못했습니다.","无法检查该任务。","無法檢查該任務。"},
    ["Проверить заново"] = {"Check again","Erneut prüfen","Vérifier à nouveau","Comprobar de nuevo","Verificar novamente","다시 확인","重新检查","重新檢查"},
    ["Источники не про Forever напрямую: сверь на месте."] = {"The sources are not about Forever directly: verify in game.","Die Quellen betreffen Forever nicht direkt: prüfe es im Spiel.","Les sources ne concernent pas directement Forever : vérifie en jeu.","Las fuentes no tratan directamente de Forever: compruébalo en el juego.","As fontes não tratam diretamente do Forever: confira no jogo.","출처가 Forever를 직접 다루지 않습니다. 게임에서 확인하세요.","来源并非直接针对 Forever：请在游戏中核实。","來源並非直接針對 Forever：請在遊戲中核實。"},
    ["Советник сверит задание с исправлениями Blizzard, списком известных ошибок и сообщениями игроков Forever."] = {"The advisor will check the quest against Blizzard’s hotfixes, the known issues list and reports from Forever players.","Der Berater gleicht die Quest mit Blizzards Hotfixes, der Liste bekannter Probleme und Berichten von Forever-Spielern ab.","Le conseiller comparera la quête aux correctifs de Blizzard, à la liste des problèmes connus et aux retours des joueurs de Forever.","El consejero comparará la misión con las correcciones de Blizzard, la lista de problemas conocidos y los informes de jugadores de Forever.","O conselheiro vai comparar a missão com as correções da Blizzard, a lista de problemas conhecidos e relatos de jogadores do Forever.","조언자가 블리자드 핫픽스, 알려진 문제 목록, Forever 플레이어 제보와 퀘스트를 대조합니다.","顾问会将任务与暴雪热修、已知问题列表以及 Forever 玩家的反馈进行核对。","顧問會將任務與暴雪熱修、已知問題列表以及 Forever 玩家的回報進行核對。"},
    ["Сверить с исправлениями"] = {"Check against hotfixes","Mit Hotfixes abgleichen","Comparer aux correctifs","Comparar con las correcciones","Comparar com as correções","핫픽스와 대조","与热修核对","與熱修核對"},
})
