    ["Нужно для задания: {1}"] = {"Needed for the quest: {1}","Für die Quest benötigt: {1}","Nécessaire pour la quête : {1}","Necesario para la misión: {1}","Necessário para a missão: {1}","퀘스트에 필요: {1}","任务所需：{1}","任務所需：{1}"},
    ["Предмет для задания"] = {"Quest item","Questgegenstand","Objet de quête","Objeto de misión","Item de missão","퀘스트 아이템","任务物品","任務物品"},
    ["Серый предмет: нужен только торговцу."] = {"A grey item: only a vendor wants it.","Ein grauer Gegenstand: Nur ein Händler will ihn.","Un objet gris : seul un marchand en veut.","Un objeto gris: solo lo quiere un vendedor.","Um item cinza: só um comerciante quer.","회색 아이템: 상인에게만 쓸모가 있습니다.","灰色物品：只有商人收。","灰色物品：只有商人收。"},
    ["Ты просил это оставить."] = {"You asked to keep this.","Du wolltest das behalten.","Tu as demandé de garder ceci.","Pediste conservar esto.","Você pediu para manter isto.","보관해 달라고 했던 물건입니다.","你要求保留它。","你要求保留它。"},
    ["У торговца освободится ячеек: {1}"] = {"Slots freed at a vendor: {1}","Beim Händler frei werdende Plätze: {1}","Emplacements libérés chez un marchand : {1}","Casillas liberadas al vender: {1}","Espaços liberados no comerciante: {1}","상인에게 팔면 {1}칸이 비워집니다","在商人处可腾出 {1} 格","在商人處可騰出 {1} 格"},
    ["Выручка около {1}."] = {"About {1} in coin.","Erlös etwa {1}.","Environ {1} de recette.","Unos {1} de ganancia.","Cerca de {1} em moedas.","수익 약 {1}.","收入约 {1}。","收入約 {1}。"},
    ["Советник оценивает остальные предметы…"] = {"The advisor is judging the remaining items…","Der Berater bewertet die übrigen Gegenstände…","Le conseiller évalue les objets restants…","El consejero está valorando los objetos restantes…","O conselheiro está avaliando os itens restantes…","조언자가 나머지 아이템을 평가하는 중…","顾问正在评估其余物品…","顧問正在評估其餘物品…"},
    ["Остальные предметы оценить не удалось."] = {"The remaining items could not be judged.","Die übrigen Gegenstände konnten nicht bewertet werden.","Les objets restants n’ont pas pu être évalués.","No se pudieron valorar los objetos restantes.","Não foi possível avaliar os itens restantes.","나머지 아이템을 평가하지 못했습니다.","无法评估其余物品。","無法評估其餘物品。"},
    ["Оценить остальные предметы"] = {"Judge the remaining items","Übrige Gegenstände bewerten","Évaluer les objets restants","Valorar los objetos restantes","Avaliar os itens restantes","나머지 아이템 평가","评估其余物品","評估其餘物品"},
    ["Можно освободить ячеек: {1}"] = {"Slots you can free: {1}","Freiräumbare Plätze: {1}","Emplacements libérables : {1}","Casillas que puedes liberar: {1}","Espaços que você pode liberar: {1}","비울 수 있는 칸: {1}","可腾出的格子：{1}","可騰出的格子：{1}"},
    ["Ты у торговца: можно продать лишнее"] = {"You are at a vendor: sell what you do not need","Du bist beim Händler: Verkaufe Überflüssiges","Tu es chez un marchand : vends le superflu","Estás con un vendedor: vende lo que sobra","Você está com um comerciante: venda o que sobra","상인 앞입니다: 필요 없는 물건을 파세요","你在商人处：可以卖掉多余物品","你在商人處：可以賣掉多餘物品"},
