T.AddLocaleRows({
    ["Куда качаться"] = {"Where to level","Wo leveln","Où monter de niveau","Dónde subir de nivel","Onde subir de nível","어디서 레벨업할까","去哪升级","去哪升級"},
    ["Зоны и подземелья под твой уровень"] = {"Zones and dungeons for your level","Zonen und Dungeons für deine Stufe","Zones et donjons pour ton niveau","Zonas y mazmorras para tu nivel","Zonas e masmorras para o seu nível","내 레벨에 맞는 지역과 던전","适合你等级的区域和地下城","適合你等級的區域和地城"},
    ["Открыть зоны"] = {"Open zones","Zonen öffnen","Voir les zones","Ver zonas","Ver zonas","지역 보기","查看区域","查看區域"},
    ["На максимальном уровне маршрут прокачки не нужен."] = {"At the level cap no levelling route is needed.","Auf Maximalstufe brauchst du keine Levelroute.","Au niveau maximum, aucun itinéraire de progression n’est nécessaire.","En el nivel máximo no hace falta una ruta de subida.","No nível máximo não é preciso uma rota de evolução.","최고 레벨에서는 레벨업 경로가 필요 없습니다.","满级后无需升级路线。","滿級後無需升級路線。"},
    ["Уровни {1}"] = {"Levels {1}","Stufen {1}","Niveaux {1}","Niveles {1}","Níveis {1}","레벨 {1}","等级 {1}","等級 {1}"},
    ["В журнале нет заданий твоего уровня"] = {"No quests of your level in the log","Keine Quests deiner Stufe im Log","Aucune quête de ton niveau dans le journal","No hay misiones de tu nivel en el registro","Nenhuma missão do seu nível no registro","목록에 내 레벨 퀘스트가 없음","日志中没有适合你等级的任务","日誌中沒有適合你等級的任務"},
    ["Самое время выбрать новую зону."] = {"A good moment to pick a new zone.","Ein guter Moment für eine neue Zone.","C’est le moment de choisir une nouvelle zone.","Buen momento para elegir una zona nueva.","Bom momento para escolher uma zona nova.","새 지역을 고를 때입니다.","正是换新区域的时候。","正是換新區域的時候。"},
    ["Заданий твоего уровня в журнале"] = {"Quests of your level in the log","Quests deiner Stufe im Log","Quêtes de ton niveau dans le journal","Misiones de tu nivel en el registro","Missões do seu nível no registro","목록의 내 레벨 퀘스트","日志中适合你等级的任务","日誌中適合你等級的任務"},
    ["Есть отдохнувший опыт"] = {"You have rested experience","Du hast Erholungsbonus","Tu as de l’expérience de repos","Tienes experiencia de descanso","Você tem experiência de descanso","휴식 경험치 있음","处于精力充沛状态","處於精力充沛狀態"},
    ["Убийства сейчас дают больше опыта: хорошее время для заданий на истребление."] = {"Kills give more experience right now: a good time for kill quests.","Kills geben gerade mehr Erfahrung: eine gute Zeit für Tötungsquests.","Tuer des monstres rapporte plus d’expérience en ce moment : bon moment pour les quêtes d’élimination.","Matar enemigos da más experiencia ahora: buen momento para misiones de matar.","Os abates dão mais experiência agora: bom momento para missões de abate.","지금은 처치 경험치가 더 많습니다. 사냥 퀘스트에 좋은 때입니다.","现在击杀经验更多：适合做击杀任务。","現在擊殺經驗更多：適合做擊殺任務。"},
    ["Советник подбирает зоны под твой уровень."] = {"The advisor is choosing zones for your level.","Der Berater wählt Zonen für deine Stufe aus.","Le conseiller choisit des zones pour ton niveau.","El consejero está eligiendo zonas para tu nivel.","O conselheiro está escolhendo zonas para o seu nível.","조언자가 내 레벨에 맞는 지역을 고르는 중입니다.","顾问正在为你的等级挑选区域。","顧問正在為你的等級挑選區域。"},
    ["Ищу зоны и подземелья для твоих уровней…"] = {"Looking for zones and dungeons for your levels…","Zonen und Dungeons für deine Stufen werden gesucht…","Recherche de zones et donjons pour tes niveaux…","Buscando zonas y mazmorras para tus niveles…","Procurando zonas e masmorras para os seus níveis…","내 레벨에 맞는 지역과 던전을 찾는 중…","正在查找适合你等级的区域和地下城…","正在查找適合你等級的區域和地城…"},
    ["Не удалось подобрать зоны."] = {"Could not choose zones.","Es konnten keine Zonen gewählt werden.","Impossible de choisir des zones.","No se pudieron elegir zonas.","Não foi possível escolher zonas.","지역을 고르지 못했습니다.","无法挑选区域。","無法挑選區域。"},
    ["Зоны"] = {"Zones","Zonen","Zones","Zonas","Zonas","지역","区域","區域"},
    ["по отзывам, спокойно"] = {"reported quiet","laut Berichten ruhig","calme d’après les retours","tranquila según los informes","tranquila segundo relatos","제보상 한산함","据反馈较清静","據回報較清靜"},
    ["по отзывам, людно"] = {"reported busy","laut Berichten voll","fréquentée d’après les retours","concurrida según los informes","cheia segundo relatos","제보상 붐빔","据反馈较拥挤","據回報較擁擠"},
    ["ты здесь"] = {"you are here","du bist hier","tu es ici","estás aquí","você está aqui","현재 위치","你在这里","你在這裡"},
    ["Людность зон игра аддонам не сообщает: это данные гайдов и отзывов."] = {"The game does not tell add-ons how crowded a zone is: this comes from guides and player reports.","Das Spiel verrät Add-ons nicht, wie voll eine Zone ist: Das stammt aus Guides und Spielerberichten.","Le jeu n’indique pas aux add-ons la fréquentation d’une zone : cela vient de guides et de retours de joueurs.","El juego no indica a los addons cuánta gente hay en una zona: esto viene de guías e informes de jugadores.","O jogo não informa aos addons a lotação de uma zona: isto vem de guias e relatos de jogadores.","게임은 지역 혼잡도를 애드온에 알려 주지 않습니다. 가이드와 플레이어 제보 기준입니다.","游戏不会向插件提供区域拥挤程度：这些来自攻略和玩家反馈。","遊戲不會向插件提供區域擁擠程度：這些來自攻略和玩家回報。"},
    ["Советник подберёт зоны и подземелья под твой уровень, включая места спокойнее."] = {"The advisor will choose zones and dungeons for your level, including quieter places.","Der Berater wählt Zonen und Dungeons für deine Stufe aus, auch ruhigere Orte.","Le conseiller choisira des zones et donjons pour ton niveau, y compris des endroits plus calmes.","El consejero elegirá zonas y mazmorras para tu nivel, incluidos lugares más tranquilos.","O conselheiro vai escolher zonas e masmorras para o seu nível, incluindo lugares mais tranquilos.","조언자가 한산한 곳을 포함해 내 레벨에 맞는 지역과 던전을 골라 줍니다.","顾问会为你的等级挑选区域和地下城，包括更清静的地方。","顧問會為你的等級挑選區域和地城，包括更清靜的地方。"},
    ["Подобрать зоны"] = {"Choose zones","Zonen auswählen","Choisir des zones","Elegir zonas","Escolher zonas","지역 고르기","挑选区域","挑選區域"},
    ["Новый диапазон уровней: посмотри, куда идти дальше"] = {"A new level range: see where to go next","Ein neuer Stufenbereich: Sieh nach, wohin es weitergeht","Nouvelle tranche de niveaux : vois où aller ensuite","Nuevo rango de niveles: mira adónde ir ahora","Nova faixa de níveis: veja para onde ir agora","새 레벨 구간: 다음 갈 곳을 확인하세요","新的等级段：看看接下来去哪","新的等級段：看看接下來去哪"},
    ["Посоветуй, где мне сейчас качаться: зона, подземелье и запасной вариант, если там толпа."] = {"Advise me where to level right now: a zone, a dungeon and a fallback if it is crowded.","Rate mir, wo ich jetzt leveln soll: eine Zone, ein Dungeon und eine Alternative, falls es voll ist.","Conseille-moi où monter de niveau maintenant : une zone, un donjon et une solution de repli s’il y a foule.","Aconséjame dónde subir de nivel ahora: una zona, una mazmorra y una alternativa si está llena.","Me diga onde subir de nível agora: uma zona, uma masmorra e uma alternativa se estiver cheia.","지금 어디서 레벨업할지 알려 줘: 지역, 던전, 붐빌 때의 대안.","建议我现在去哪升级：一个区域、一个地下城，以及人多时的备选。","建議我現在去哪升級：一個區域、一個地城，以及人多時的備選。"},
})
-- Research on request: the setting and the buttons that start what used to start by itself.
T.AddLocaleRows({
    ["Исследования журнала"] = {"Journal research","Feldtagebuch-Recherchen","Recherches du journal","Investigación del diario","Pesquisas do diário","일지 조사","冒险日志研究","冒險日誌研究"},
    ["Только по кнопке"] = {"Only on click","Nur per Klick","Seulement au clic","Solo al hacer clic","Só ao clicar","버튼을 누를 때만","仅在点击时","僅在點擊時"},
    ["Автоматически"] = {"Automatic","Automatisch","Automatique","Automático","Automático","자동","自动","自動"},
    ["Советник готовит раздел, только когда ты нажмёшь в нём кнопку. Каждое исследование расходует лимит твоей подписки."] = {"The advisor prepares a section only when you press its button. Every research job spends your subscription's allowance.","Der Berater bereitet einen Abschnitt nur vor, wenn du dessen Schaltfläche drückst. Jede Recherche verbraucht das Kontingent deines Abos.","Le conseiller ne prépare une section que lorsque tu appuies sur son bouton. Chaque recherche consomme le quota de ton abonnement.","El consejero prepara una sección solo cuando pulsas su botón. Cada investigación gasta el límite de tu suscripción.","O conselheiro prepara uma seção só quando você pressiona o botão dela. Cada pesquisa consome o limite da sua assinatura.","조언자는 섹션의 버튼을 누를 때만 내용을 준비합니다. 조사할 때마다 구독 사용 한도가 소모됩니다.","只有在你点击分区中的按钮时，顾问才会准备该分区。每次研究都会消耗你的订阅额度。","只有在你點擊分區中的按鈕時，顧問才會準備該分區。每次研究都會消耗你的訂閱額度。"},
    ["Советник сам готовит сводку исправлений и советы по классу после входа в игру, а остальные разделы — когда ты их открываешь. Каждое исследование расходует лимит твоей подписки."] = {"The advisor prepares the hotfix digest and class advice by itself after you log in, and the other sections when you open them. Every research job spends your subscription's allowance.","Der Berater bereitet die Hotfix-Übersicht und die Klassentipps nach dem Einloggen von selbst vor, die übrigen Abschnitte beim Öffnen. Jede Recherche verbraucht das Kontingent deines Abos.","Le conseiller prépare de lui-même le résumé des correctifs et les conseils de classe après ta connexion, et les autres sections quand tu les ouvres. Chaque recherche consomme le quota de ton abonnement.","El consejero prepara por sí mismo el resumen de correcciones y los consejos de clase al entrar en el juego, y las demás secciones cuando las abres. Cada investigación gasta el límite de tu suscripción.","O conselheiro prepara sozinho o resumo de correções e as dicas de classe depois que você entra no jogo, e as outras seções quando você as abre. Cada pesquisa consome o limite da sua assinatura.","조언자가 접속 후 핫픽스 요약과 직업 조언을 스스로 준비하고, 나머지 섹션은 열 때 준비합니다. 조사할 때마다 구독 사용 한도가 소모됩니다.","顾问会在你登录后自动准备热修摘要和职业建议，其余分区在你打开时准备。每次研究都会消耗你的订阅额度。","顧問會在你登入後自動準備熱修摘要和職業建議，其餘分區在你開啟時準備。每次研究都會消耗你的訂閱額度。"},
    ["Исследований в сутки, не больше"] = {"Research jobs a day, at most","Recherchen pro Tag, höchstens","Recherches par jour, au maximum","Investigaciones al día, como máximo","Pesquisas por dia, no máximo","하루 조사 횟수 상한","每日研究次数上限","每日研究次數上限"},
    ["Собрать советы по классу"] = {"Gather class advice","Klassentipps sammeln","Réunir les conseils de classe","Reunir consejos de clase","Reunir dicas de classe","직업 조언 모으기","收集职业建议","收集職業建議"},
    ["Советник соберёт для твоего класса и уровня приоритет характеристик, классовые задания и ранги, которые стоит купить или пропустить."] = {"The advisor will gather stat priorities, class quests, and the ranks worth buying or skipping for your class and level.","Der Berater sammelt für deine Klasse und Stufe Werteprioritäten, Klassenquests und die Ränge, die sich lohnen oder die du auslassen kannst.","Le conseiller réunira pour ta classe et ton niveau les priorités de caractéristiques, les quêtes de classe et les rangs à acheter ou à ignorer.","El consejero reunirá para tu clase y nivel las prioridades de estadísticas, las misiones de clase y los rangos que conviene comprar u omitir.","O conselheiro vai reunir para a sua classe e nível as prioridades de atributos, as missões de classe e os graus que vale comprar ou pular.","조언자가 내 직업과 레벨에 맞는 능력치 우선순위, 직업 퀘스트, 배우거나 건너뛸 주문 등급을 모아 줍니다.","顾问会为你的职业和等级收集属性优先级、职业任务，以及值得购买或可以跳过的法术等级。","顧問會為你的職業和等級收集屬性優先順序、職業任務，以及值得購買或可以跳過的法術等級。"},
})
