T.AddLocaleRows({
    ["Не удалось найти Codex CLI. Проверь путь в настройках Looking for Guidance."] = {"Codex CLI was not found. Check its path in the Looking for Guidance settings.","Codex CLI wurde nicht gefunden. Prüfe den Pfad in den Einstellungen von Looking for Guidance.","Codex CLI est introuvable. Vérifie son chemin dans les réglages de Looking for Guidance.","No se encontró Codex CLI. Comprueba su ruta en la configuración de Looking for Guidance.","O Codex CLI não foi encontrado. Verifique o caminho nas configurações do Looking for Guidance.","Codex CLI를 찾을 수 없습니다. Looking for Guidance 설정에서 경로를 확인하세요.","未找到 Codex CLI。请在 Looking for Guidance 的设置中检查其路径。","找不到 Codex CLI。請在 Looking for Guidance 的設定中檢查其路徑。"},
    ["Войди в ChatGPT: выбери «Войти в ChatGPT…» в меню Looking for Guidance."] = {"Sign in to ChatGPT: choose “Sign in to ChatGPT…” in the Looking for Guidance menu.","Melde dich bei ChatGPT an: Wähle „Bei ChatGPT anmelden…“ im Menü von Looking for Guidance.","Connecte-toi à ChatGPT : choisis « Se connecter à ChatGPT… » dans le menu de Looking for Guidance.","Inicia sesión en ChatGPT: elige «Iniciar sesión en ChatGPT…» en el menú de Looking for Guidance.","Entre no ChatGPT: escolha “Entrar no ChatGPT…” no menu do Looking for Guidance.","ChatGPT에 로그인하세요: Looking for Guidance 메뉴에서 ‘ChatGPT에 로그인…’을 선택하세요.","请登录 ChatGPT：在 Looking for Guidance 菜单中选择“登录 ChatGPT…”。","請登入 ChatGPT：在 Looking for Guidance 選單中選擇「登入 ChatGPT…」。"},
    ["Подключаюсь к Codex…"] = {"Connecting to Codex…","Verbinde mit Codex…","Connexion à Codex…","Conectando con Codex…","Conectando ao Codex…","Codex에 연결하는 중…","正在连接 Codex…","正在連線 Codex…"},
    ["Не удалось найти Claude Code. Установи его или выбери другого советника в меню Looking for Guidance."] = {"Claude Code was not found. Install it or choose another advisor in the Looking for Guidance menu.","Claude Code wurde nicht gefunden. Installiere es oder wähle im Menü von Looking for Guidance einen anderen Berater.","Claude Code est introuvable. Installe-le ou choisis un autre conseiller dans le menu de Looking for Guidance.","No se encontró Claude Code. Instálalo o elige otro consejero en el menú de Looking for Guidance.","O Claude Code não foi encontrado. Instale-o ou escolha outro conselheiro no menu do Looking for Guidance.","Claude Code를 찾을 수 없습니다. 설치하거나 Looking for Guidance 메뉴에서 다른 조언자를 선택하세요.","未找到 Claude Code。请安装它，或在 Looking for Guidance 菜单中选择其他顾问。","找不到 Claude Code。請安裝它，或在 Looking for Guidance 選單中選擇其他顧問。"},
    ["Войди в Claude Code: выбери «Войти в Claude Code…» в меню Looking for Guidance."] = {"Sign in to Claude Code: choose “Sign in to Claude Code…” in the Looking for Guidance menu.","Melde dich bei Claude Code an: Wähle „Bei Claude Code anmelden…“ im Menü von Looking for Guidance.","Connecte-toi à Claude Code : choisis « Se connecter à Claude Code… » dans le menu de Looking for Guidance.","Inicia sesión en Claude Code: elige «Iniciar sesión en Claude Code…» en el menú de Looking for Guidance.","Entre no Claude Code: escolha “Entrar no Claude Code…” no menu do Looking for Guidance.","Claude Code에 로그인하세요: Looking for Guidance 메뉴에서 ‘Claude Code에 로그인…’을 선택하세요.","请登录 Claude Code：在 Looking for Guidance 菜单中选择“登录 Claude Code…”。","請登入 Claude Code：在 Looking for Guidance 選單中選擇「登入 Claude Code…」。"},
    ["Подключаюсь к Claude Code…"] = {"Connecting to Claude Code…","Verbinde mit Claude Code…","Connexion à Claude Code…","Conectando con Claude Code…","Conectando ao Claude Code…","Claude Code에 연결하는 중…","正在连接 Claude Code…","正在連線 Claude Code…"},
    ["Не найден ни один советник. Установи Claude Code или Codex CLI: ссылки есть в меню Looking for Guidance."] = {"No advisor was found. Install Claude Code or Codex CLI: the Looking for Guidance menu has the links.","Kein Berater gefunden. Installiere Claude Code oder Codex CLI: Die Links stehen im Menü von Looking for Guidance.","Aucun conseiller trouvé. Installe Claude Code ou Codex CLI : les liens sont dans le menu de Looking for Guidance.","No se encontró ningún consejero. Instala Claude Code o Codex CLI: los enlaces están en el menú de Looking for Guidance.","Nenhum conselheiro encontrado. Instale o Claude Code ou o Codex CLI: os links estão no menu do Looking for Guidance.","조언자를 찾을 수 없습니다. Claude Code 또는 Codex CLI를 설치하세요. 링크는 Looking for Guidance 메뉴에 있습니다.","未找到任何顾问。请安装 Claude Code 或 Codex CLI：链接在 Looking for Guidance 菜单中。","找不到任何顧問。請安裝 Claude Code 或 Codex CLI：連結在 Looking for Guidance 選單中。"},
})
